class Solution {
public:
    double calculateBill(int units) {
        if (units < 0) {
            return -1.00;
        }

        double bill = 0.0;

        if (units <= 100) {
            bill = units * 1.50;
        } else if (units <= 200) {
            bill = (100 * 1.50) + ((units - 100) * 2.50);
        } else if (units <= 300) {
            bill = (100 * 1.50) + (100 * 2.50) + ((units - 200) * 4.00);
        } else {
            bill = (100 * 1.50) + (100 * 2.50) + (100 * 4.00) + ((units - 300) * 6.50);
        }

        if (bill < 50.00) {
            bill = 50.00;
        }

        if (bill > 400.00) {
            bill = bill + (bill * 0.15);
        }

        return bill;
    }
};

