class Solution {
public:
    string isArmstrong(long long n) {
        long long original = n;

        // Step 1: Count digits (k)
        int k = 0;
        long long temp = n;
        while (temp > 0) {
            k++;
            temp /= 10;
        }

        // Step 2: Sum each digit raised to the power k
        long long sum = 0;
        temp = n;
        while (temp > 0) {
            int digit = temp % 10;
            // Compute digit^k using a small loop (avoid pow() floating-point issues)
            long long power = 1;
            for (int i = 0; i < k; i++) {
                power *= digit;
            }
            sum += power;
            temp /= 10;
        }

        return (sum == original) ? "ARMSTRONG" : "NOT ARMSTRONG";
    }
};

