class Solution {
public:
    int binarySearch(int arr[], int n, int target) {
        int lo = 0;
        int hi = n - 1;

        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;   // avoids overflow

            if (arr[mid] == target) {
                return mid;
            } else if (arr[mid] < target) {
                lo = mid + 1;               // search right half
            } else {
                hi = mid - 1;               // search left half
            }
        }

        return -1;
    }
};

